// Full Priority 2 Queue (210 completed genuine pathways — 100.00% of the 210 target queue)
export const PRIORITY2_FULL_QUEUE: Priority2PathwayAudit[] = [...PRIORITY2_COMPLETED_PATHWAYS];

/**
 * Public-safe projection for Priority 2 pathways.
 * Strips internal audit/classification notes (correctiveClassificationNotes) and prevents
 * any unverified or NOT_OFFERED record from being exposed as a verified public pathway.
 */
export function getPublicPriority2PathwayView(pathwayId: string): Omit<Priority2PathwayAudit, 'correctiveClassificationNotes'> | null {
  const found = PRIORITY2_COMPLETED_PATHWAYS.find(p => p.id === pathwayId);
  const rawSt = String(found?.verificationStatus || '').toUpperCase();
  if (
    !found ||
    (found as any).isQuarantined === true ||
    (found as any).publicEligible === false ||
    ['NOT_OFFERED', 'AWAITING_VERIFICATION', 'CONFLICTING_EVIDENCE', 'EXPIRED', 'QUARANTINED', 'REJECTED'].includes(rawSt)
  ) {
    return null;
  }
  const { correctiveClassificationNotes: _strippedInternalNotes, ...publicSafeRecord } = found as any;
  delete publicSafeRecord.reviewerNotes;
  delete publicSafeRecord.internalReviewNotes;
  delete publicSafeRecord.isPilotSample;
  if (Array.isArray(publicSafeRecord.sections)) {
    publicSafeRecord.sections = publicSafeRecord.sections.filter((sec: any) => {
      const s = String(sec?.status || '').toUpperCase();
      return !['AWAITING_VERIFICATION', 'CONFLICTING_EVIDENCE', 'EXPIRED', 'QUARANTINED', 'REJECTED'].includes(s);
    });
  }
  return publicSafeRecord;
}

